ssion":"83..93"},{"name":"c","expression":"85..98"}],"conditions":["a != 50","b != c","round((a*b+(100-a)*c)/10) != 10*c","round(1000*(100-a)*c/(a*b+(100-a)*c)) != 10*c","round(1000*(100-a)*c/(a*b+(100-a)*c)) != 10*a","round(1000*(100-a)*c/(a*b+(100-a)*c)) != round(a*b/10)","round(a*b/10) != 10*a"],"blanks":[{"expectedAnswer":"{{eval:c/100;d}}","expectedErrors":[{"answer":"{{eval:round((a*b+(100-a)*c)/10)/1000;d}}","message":"Tu as donné la proportion de valises qui ont réussi les tests, sans condition : $P_{\\overline{A}}(B)$ se lit dans la phrase « parmi les valises à deux roues ».","label":"P(B) au lieu de P_Ā(B)"},{"answer":"{{eval:b/100;d}}","message":"Tu as lu la phrase des valises à **quatre** roues : $\\overline{A}$ désigne les valises à deux roues.","label":"P_A(B) au lieu de P_Ā(B)"},{"answer":"{{eval:round(1000*(100-a)*c/(a*b+(100-a)*c))/1000;d}}","message":"Tu as inversé condition et évènement : dans $P_{\\overline{A}}(B)$, la condition est $\\overline{A}$ (« parmi les valises à deux roues »).","label":"P_B(Ā) au lieu de P_Ā(B)"}]},{"expectedAnswer":"{{eval:round(a*b/10)/1000;d}}","expectedErrors":[{"answer":"{{eval:b/100;d}}","message":"Tu as lu une phrase « parmi… » : $P(A\\cap B)$ est la proportion de **toutes** les valises qui ont quatre roues **et** ont réussi les tests.","label":"P_A(B) au lieu de P(A ∩ B)"},{"answer":"{{eval:a/100;d}}","message":"$P(A)$ ne compte que les valises à quatre roues : $A\\cap B$ demande aussi que la valise ait réussi les tests.","label":"P(A) au lieu de P(A ∩ B)"}]},{"expectedAnswer":"{{eval:round(1000*(100-a)*c/(a*b+(100-a)*c))/1000;d}}","expectedErrors":[{"answer":"{{eval:c/100;d}}","message":"Tu as inversé condition et évènement : dans $P_B(\\overline{A})$, la condition est $B$ (« parmi les valises qui ont réussi les tests »).","label":"P_Ā(B) au lieu de P_B(Ā)"},{"answer":"{{eval:round((a*b+(100-a)*c)/10)/1000;d}}","message":"Tu as donné la proportion de valises qui ont réussi : on demande, parmi elles, la proportion de valises à deux roues.","label":"P(B) au lieu de P_B(Ā)"}]}],"correction":{"steps":["« Parmi les… » désigne la condition, écrite en indice ; une phrase sans « parmi » donne une probabilité sans condition.","« Parmi les valises à deux roues, ${{c}}\\,\\%$ ont réussi les tests » : $P_{\\overline{A}}(B)=\\textcolor{{{color:primary.0}}}{ {{eval:c/100;d}} }$.","« ${{eval:round(a*b/10)/10;d}}\\,\\%$ des valises ont quatre roues et ont réussi les tests » : $P(A\\cap B)=\\textcolor{{{color:primary.0}}}{ {{eval:round(a*b/10)/1000;d}} }$.","« Parmi les valises qui ont réussi les tests, ${{eval:round(1000*(100-a)*c/(a*b+(100-a)*c))/10;d}}\\,\\%$ ont deux roues » : $P_B(\\overline{A})=\\textcolor{{{color:primary.0}}}{ {{eval:round(1000*(100-a)*c/(a*b+(100-a)*c))/1000;d}} }$."]},"hint":"« Parmi les … » désigne la condition : c'est l'évènement écrit en indice."}]$q$::jsonb
